    "code": "--liquibase formatted sql\n\n--changeset chetra.seng:002-service-certificates-and-product-no\nCREATE TABLE IF NOT EXISTS service_certificates (\n    version INTEGER DEFAULT 1,\n    created_date timestamp(6) with time zone,\n    id bigint generated by default as identity,\n    service_id bigint not null,\n    updated_date timestamp(6) with time zone,\n    cert_code varchar(10),\n    cert_type varchar(20) constraint ck_service_certificates_cert_type check (cert_type in ('LICENSE','PRODUCT')),\n    cert_prefix varchar(50),\n    created_by varchar(255),\n    updated_by varchar(255),\n    constraint pk_service_certificates primary key (id),\n    constraint uk_service_certificates_service_cert unique (service_id, cert_code, cert_type),\n    constraint fk_service_certificates_service_id foreign key (service_id) references services (service_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_service_certificates_service_id ON service_certificates (service_id);\n\nINSERT INTO service_certificates (service_id, cert_code, cert_type, cert_prefix, created_date)\nSELECT service_id, cert_code, cert_type, cert_prefix, now()\nFROM services\nWHERE cert_code IS NOT NULL;\n\nALTER TABLE services DROP CONSTRAINT IF EXISTS ck_services_cert_type;\nALTER TABLE services DROP COLUMN IF EXISTS cert_code;\nALTER TABLE services DROP COLUMN IF EXISTS cert_type;\nALTER TABLE services DROP COLUMN IF EXISTS cert_prefix;\n\nALTER TABLE licenses ADD COLUMN IF NOT EXISTS product_no varchar(255);\n\n-- Backfill: existing rows for a PRODUCT-cert service (today, only GDHT-CN-L) stored their product\n-- number in license_no, since that was the only column. Mirror it into product_no so the renewal\n-- reuse-check (which now reads product_no) finds it.\nUPDATE licenses l\nSET product_no = l.license_no\nFROM regulatory_registrations r\nJOIN services s ON s.service_code = r.service_code\nJOIN service_certificates sc ON sc.service_id = s.service_id AND sc.cert_type = 'PRODUCT'\nWHERE r.license_id = l.id AND l.license_no IS NOT NULL;\n--rollback UPDATE licenses SET product_no = NULL;\n--rollback ALTER TABLE licenses DROP COLUMN product_no;\n--rollback ALTER TABLE services ADD COLUMN cert_code varchar(10);\n--rollback ALTER TABLE services ADD COLUMN cert_type varchar(20) constraint ck_services_cert_type check (cert_type in ('LICENSE','PRODUCT'));\n--rollback ALTER TABLE services ADD COLUMN cert_prefix varchar(50);\n--rollback UPDATE services s SET cert_code = c.cert_code, cert_type = c.cert_type, cert_prefix = c.cert_prefix FROM (SELECT DISTINCT ON (service_id) service_id, cert_code, cert_type, cert_prefix FROM service_certificates ORDER BY service_id, id) c WHERE c.service_id = s.service_id;\n--rollback DROP TABLE service_certificates;"
