    "code": "--liquibase formatted sql\n\n--changeset esb:003-license-old-certificate splitStatements:false\n--comment: Old-certificate columns for re-registered (pre-system) licenses, plus a unique index on license_no. The index is only created when no duplicate numbers exist yet, so the columns are always added even on a database that already holds duplicates (application-level checks still apply there).\nALTER TABLE licenses ADD COLUMN IF NOT EXISTS old_license_no varchar(255);\nALTER TABLE licenses ADD COLUMN IF NOT EXISTS old_issue_date date;\nALTER TABLE licenses ADD COLUMN IF NOT EXISTS old_expiry_date date;\n\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM licenses WHERE license_no IS NOT NULL GROUP BY license_no HAVING count(*) > 1) THEN\n        CREATE UNIQUE INDEX IF NOT EXISTS uk_licenses_license_no ON licenses (license_no) WHERE license_no IS NOT NULL;\n    END IF;\nEND $$;\n--rollback DROP INDEX IF EXISTS uk_licenses_license_no;\n--rollback ALTER TABLE licenses DROP COLUMN old_license_no, DROP COLUMN old_issue_date, DROP COLUMN old_expiry_date;"
